#!/usr/bin/env bash
# Shared settings for the Crewflow cost/performance harness. Sourced by every script in this folder; never executed.
# Nothing here is a secret: secrets live in $COST_SECRETS (outside the repo, generated by scripts/gen-secrets.sh).

COST_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO="$(cd "$COST_DIR/../../.." && pwd)" # packages/rab-e2e-testing/cost -> repo root (no git call: see MSYS note below)
# Outside the repo by default. Override with env vars if the machine layout differs.
COST_SECRETS="${COST_SECRETS:-/c/rab-ai-wt/cost-secrets/cost.env}"
COST_WORK="${COST_WORK:-/c/rab-ai-wt/cost-work}"
COST_PROJECT=crewflow-cost
COST_COMPOSE_FILE="$COST_DIR/docker-compose.cost.yml"

# Host ports (loopback only). Chosen to avoid the dev stack (3000, 5173, 15432), crewflow-test-* (15436, 16391-16399)
# and the e2e stack (3300, 15470, 16470); check_ports_subnet (lib/guard.sh) re-verifies this before every run.
export COST_PG_PORT="${COST_PG_PORT:-25470}"
export COST_REDIS_PORT="${COST_REDIS_PORT:-26470}"
export COST_MINIO_PORT="${COST_MINIO_PORT:-29070}"
export COST_API_PORT="${COST_API_PORT:-23070}"
export COST_SUBNET="${COST_SUBNET:-172.31.70.0/24}"

# Git Bash would rewrite '/rest/v1/...' arguments into Windows paths without this.
export MSYS_NO_PATHCONV=1

die() { echo "[cost] ERROR: $*" >&2; exit 1; }
log() { echo "[cost] $(date -u +%H:%M:%SZ) $*" >&2; }

# Windows path for docker -v when running under Git Bash; identity elsewhere.
hostpath() { if command -v cygpath >/dev/null 2>&1; then cygpath -m "$1"; else printf '%s' "$1"; fi; }

load_secrets() {
  [ -f "$COST_SECRETS" ] || die "secrets file $COST_SECRETS missing; run scripts/gen-secrets.sh"
  set -a
  # shellcheck disable=SC1090
  . "$COST_SECRETS"
  set +a
  # The worker's provisioner URL is a compose pass-through (docker-compose.cost.yml); COST_NO_PROVISIONER_URL=1 leaves it out.
  if [ "${COST_NO_PROVISIONER_URL:-0}" = 1 ]; then unset CREWFLOW_PROVISIONER_DATABASE_URL
  else export CREWFLOW_PROVISIONER_DATABASE_URL="postgres://crewflow:${CREWFLOW_PW}@pg:5432/rab"; fi
}

# COST_TAG selects the image pair crewflow-cost/{server,worker}:$COST_TAG.
require_tag() {
  [ -n "${COST_TAG:-}" ] || die "COST_TAG is not set (image tag, e.g. the short commit)"
  case "$COST_TAG" in latest|*[!A-Za-z0-9._-]*) die "refusing COST_TAG='$COST_TAG' (never 'latest'; [A-Za-z0-9._-] only)";; esac
  export COST_TAG
}

# Always this project and this file: COMPOSE_PROJECT_NAME / COMPOSE_FILE / COMPOSE_PROFILES from the caller's shell
# cannot redirect it to another project.
dc() { env -u COMPOSE_PROJECT_NAME -u COMPOSE_FILE -u COMPOSE_PROFILES docker compose -p "$COST_PROJECT" --env-file "$(hostpath "$COST_SECRETS")" -f "$(hostpath "$COST_COMPOSE_FILE")" "$@"; }

# Host node scripts get Windows-style paths (Node cannot open /c/... paths).
node_env() { local s="$1"; shift; COST_SECRETS="$(hostpath "$COST_SECRETS")" COST_OUT="$(hostpath "$OUT")" COST_API_PORT="$COST_API_PORT" node "$(hostpath "$s")" "$@"; }

# Superuser psql INSIDE the disposable Postgres container (unix socket; no host client needed, never another DB).
psql_su() { docker exec -i costaudit-pg psql -X -v ON_ERROR_STOP=1 -U rab -d rab -Atq "$@"; }
q() { psql_su -c "$1"; }

redis_cli() { docker exec costaudit-redis redis-cli -a "$REDIS_PW" --no-auth-warning "$@"; }

# Total CPU microseconds consumed by a container's cgroup (cgroup v2).
cg_cpu_usec() { docker exec "$1" cat /sys/fs/cgroup/cpu.stat | awk '/^usage_usec/{print $2}'; }

# Isolation guards (container guard, project-scope guard, main-checkout drift guard, dev-state guard).
# shellcheck source=guard.sh
. "$COST_DIR/lib/guard.sh"

# Hard refusals at source time, before any script does anything: the harness never runs from, writes into or mounts
# the main checkout ($COST_MAIN_CHECKOUT, default C:/Rab-recruit). Its compose binds are relative to this folder, so a
# copy of the harness inside the main checkout would turn them into main-checkout mounts.
assert_outside_main "the harness folder (COST_DIR)" "$COST_DIR"
assert_outside_main "the repo the images are archived from (REPO)" "$REPO"
assert_outside_main "COST_WORK" "$COST_WORK"
assert_outside_main "COST_SECRETS" "$COST_SECRETS"
[ -z "${OUT:-}" ] || assert_outside_main "the results directory (OUT)" "$OUT"
